"""Counting and deterministic ranking for decoded text."""

from __future__ import annotations

import re


def count_words(text: str) -> list[str]:
    """Return R3 word tokens in their original order."""
    return re.findall(r"[a-z0-9]+", text.lower())


def count_text(text: str) -> dict[str, int]:
    """Return the line, word, and character counts for decoded text."""
    return {
        "lines": len(text.splitlines()),
        "words": len(count_words(text)),
        "chars": len(text),
    }


def rank_words(text: str, top: int = 3) -> list[dict[str, int | str]]:
    """Return the N most frequent words with deterministic tie handling."""
    counts: dict[str, int] = {}
    for word in count_words(text):
        counts[word] = counts.get(word, 0) + 1

    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:top]
    return [{"word": word, "count": count} for word, count in ranked]


def analyze(text: str, top: int = 3) -> dict[str, object]:
    """Return the complete result object used by both output formats."""
    return {
        **count_text(text),
        "top": rank_words(text, top),
    }

"""Command-line entry point for wordstat."""

from __future__ import annotations

import argparse
import sys

from .analyzer import analyze
from .output import render_json, render_text


def positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as error:
        raise argparse.ArgumentTypeError(f"{value!r} is not an integer") from error
    if parsed < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return parsed


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="wordstat")
    parser.add_argument("--json", action="store_true", help="emit JSON output")
    parser.add_argument(
        "--top",
        type=positive_int,
        default=3,
        metavar="N",
        help="number of frequent words to include (default: 3)",
    )
    parser.add_argument("file", metavar="FILE", help="UTF-8 text file to analyze")
    return parser


def fail(message: str, exit_code: int) -> int:
    print(f"wordstat: error: {message}", file=sys.stderr)
    return exit_code


def main(argv: list[str] | None = None) -> int:
    sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    args = build_parser().parse_args(argv)

    try:
        with open(args.file, "r", encoding="utf-8-sig", newline="") as source:
            text = source.read()
    except UnicodeDecodeError:
        return fail(f"{args.file}: not valid UTF-8", 3)
    except OSError:
        return fail(f"{args.file}: cannot read file", 3)

    result = analyze(text, args.top)
    rendered = render_json(result) if args.json else render_text(result)
    sys.stdout.write(rendered)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

